/* From Uiverse.io by htwarriors108 - Tags: glassmorphism, facebook, button, hover, share, social media, clean, links, hover effect, buttons */
.__UIV_SCOPE__ button {
  position: relative;
  border: none;
  margin: 10px;
  background-color: transparent;
}

.__UIV_SCOPE__ button a {
  width: 80px;
  height: 80px;
  border-radius: 15px;
  display: flex;
  justify-content: center;
  align-items: center;
  border: 1px solid rgba(255, 255, 255, 0.5);
  border-right: 1px solid rgba(255, 255, 255, 0.2);
  border-bottom: 1px solid rgba(255, 255, 255, 0.2);
  box-shadow: 0 5px 45px rgba(0, 0, 0, 0.3);
  backdrop-filter: blur(2px);
  transition: 0.5s;
  overflow: hidden;
  background-color: rgba(255, 255, 255, 0.1);
}

.__UIV_SCOPE__ button a:hover {
  transform: translateY(-20px);
}

.__UIV_SCOPE__ button a::before {
  content: '';
  position: absolute;
  top: 0;
  left: 0;
  width: 50px;
  height: 100%;
  background-color: rgba(255, 255, 255, 0.5);
  transform: skewX(45deg) translateX(150px);
  transition: 0.5s ease;
}

.__UIV_SCOPE__ button a:hover::before {
  transform: skewX(45deg) translateX(-150px);
}

.__UIV_SCOPE__ button a svg {
  width: 3em;
}

.__UIV_SCOPE__ #facebook {
  color: rgba(10, 128, 236, 0.7);
}
